// Validação do payload de medição
const input = $input.first().json;

// Campos obrigatórios
const camposObrigatorios = ['obra_id', 'periodo_inicio', 'periodo_fim'];
const camposFaltando = camposObrigatorios.filter(campo => !input[campo]);

if (camposFaltando.length > 0) {
  throw new Error(`Campos obrigatórios faltando: ${camposFaltando.join(', ')}`);
}

const medicaoRequest = {
  obra_id: input.obra_id,
  periodo_inicio: input.periodo_inicio,
  periodo_fim: input.periodo_fim,
  aplicar_igpm: input.aplicar_igpm !== false,
  taxa_igpm: parseFloat(input.taxa_igpm) || 0,
  observacoes: input.observacoes || ''
};

return { json: medicaoRequest };

// Calcular valores da medição
const request = $('Validar Payload').first().json;
const programacoes = $('Buscar Programações Executadas').first().json;
const obra = $('Buscar Dados da Obra').first().json[0];
const valoresUnitarios = $('Buscar Valores Unitários').first().json;

if (!programacoes || programacoes.length === 0) {
  return {
    json: {
      erro: true,
      mensagem: 'Nenhuma programação executada encontrada no período'
    }
  };
}

// Agrupar quantidades por serviço
const servicosExecutados = {};

programacoes.forEach(prog => {
  if (prog.servicos_executados) {
    prog.servicos_executados.forEach(serv => {
      const key = serv.servico_id || serv.servico;
      if (!servicosExecutados[key]) {
        servicosExecutados[key] = {
          servico: serv.servico,
          unidade: serv.unidade || 'm²',
          quantidade: 0
        };
      }
      servicosExecutados[key].quantidade += parseFloat(serv.quantidade) || 0;
    });
  }
});

// Aplicar valores unitários
let valorBruto = 0;
const itens = [];

Object.values(servicosExecutados).forEach(serv => {
  const valorUnit = valoresUnitarios.find(v => 
    v.servico.toLowerCase() === serv.servico.toLowerCase()
  );

  const valor = valorUnit ? valorUnit.valor : 0;
  const subtotal = serv.quantidade * valor;

  itens.push({
    servico: serv.servico,
    unidade: serv.unidade,
    quantidade: serv.quantidade,
    valor_unitario: valor,
    subtotal: subtotal
  });

  valorBruto += subtotal;
});

// Se não houver serviços detalhados, usar valor proporcional
if (itens.length === 0 && obra.valor_total > 0) {
  const percentualExecutado = programacoes.length / 10; // Estimativa simples
  valorBruto = obra.valor_total * percentualExecutado;

  itens.push({
    servico: 'Serviços executados no período',
    unidade: 'vb',
    quantidade: 1,
    valor_unitario: valorBruto,
    subtotal: valorBruto
  });
}

// Aplicar IGP-M se configurado
let valorCorrigido = valorBruto;
let correcaoIgpm = 0;

if (request.aplicar_igpm && request.taxa_igpm > 0) {
  correcaoIgpm = valorBruto * (request.taxa_igpm / 100);
  valorCorrigido = valorBruto + correcaoIgpm;
}

const medicao = {
  obra_id: request.obra_id,
  numero: `MED-${Date.now()}`,
  periodo_inicio: request.periodo_inicio,
  periodo_fim: request.periodo_fim,
  programacoes_ids: programacoes.map(p => p.id),
  itens: itens,
  valor_bruto: Math.round(valorBruto * 100) / 100,
  taxa_igpm: request.taxa_igpm || 0,
  correcao_igpm: Math.round(correcaoIgpm * 100) / 100,
  valor_total: Math.round(valorCorrigido * 100) / 100,
  status: 'em_elaboracao',
  observacoes: request.observacoes,
  cliente_nome: obra.cliente_nome,
  cliente_email: obra.cliente_email,
  created_at: new Date().toISOString()
};

return { json: medicao };

